      {
        "factor": "Credible intelligence reports of intensified chemical weapons use by Russia in Ukraine",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "European intelligence statements describe increased use of banned agents (chloropicrin/CS), signaling higher risk of CW deployment despite attribution challenges."
      },
      {
        "factor": "OPCW technical findings of riot-control agent CS in Ukraine",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "OPCW-confirmed CS detections indicate battlefield chemical-agent deployment, elevating probability of CW use even if responsibility remains uncertain."
      },
      {
        "factor": "Attribution uncertainty about responsibility for alleged CW use",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Ambiguity about who used the agents tempers the push from CS findings, reducing confidence in a state-actor attribution."
      },
      {
        "factor": "Strengthened international norms and verification under the CWC",
        "direction": "down",
        "magnitude": "moderate",
        "rationale": "Robust verification and sanctions reduce incentives and increase detection risk, damping the probability."
      },
      {
        "factor": "Escalation dynamics in the Ukraine conflict that could lower barriers to use",
        "direction": "up",
        "magnitude": "moderate",
        "rationale": "Rising battlefield intensity may create incentives to employ CW, increasing probability."
      }
    ],
    "synthesis_rationale": "The posterior of 0.34 results from integrating upward signals from intelligence and OPCW findings with downward pressures from attribution uncertainty and strong normative constraints under the CWC. Signals are potentially correlated, so updates were conceptually down-weighted to avoid double-counting, yielding a low-to-moderate risk with substantial remaining uncertainty."
  }
}

